[MITM]
hostname = testflight.apple.com

[Script]
http-request ^https?:\/\/testflight\.apple\.com\/v3\/accounts\/.*\/apps$, script-path=https://kelee.one/Resource/JavaScript/TestFlight/TF_keys.js
http-request ^https://testflight.apple.com/join/(.*), script-path=https://kelee.one/Resource/JavaScript/TestFlight/TF_keys.js
自动加入TF = type=cron, cronexp={TimingParameters}, script-path=https://kelee.one/Resource/JavaScript/TestFlight/Auto_join_TF.js, timeout=180
